use function Phit\{fit_ols, predict};

// $housing: docs/data/housing.csv as named columns
$fit = fit_ols('monthly_rent ~ area_m2 + bedrooms', $housing);
foreach ($fit['named'] as $name => $b) {
    printf("%-12s %8.2f\n", $name, $b);
}

$p = predict(
    $fit,
    ['area_m2' => [60, 90], 'bedrooms' => [1, 3]],
    interval: 'prediction',
);
foreach ($p['fit'] as $i => $rent) {
    printf(
        "%.2f [%.2f, %.2f]\n",
        $rent, $p['lower'][$i], $p['upper'][$i],
    );
}
